{"code":"def transform(grid):
    h=len(grid); w=len(grid[0])
    # Find whether the clean pattern is organized by rows or columns.
    candidates=[]
    for axis in (0,1):
        vals=[]
        for p in (0,1):
            a=[]
            for r in range(h):
                for c in range(w):
                    if ((r if axis==0 else c)&1)==p: a.append(grid[r][c])
            counts={x:a.count(x) for x in set(a)}
            vals.append(max(counts,key=counts.get))
        score=sum(grid[r][c]==vals[((r if axis==0 else c)&1)] for r in range(h) for c in range(w))
        candidates.append((score,axis,vals))
    _,axis,vals=max(candidates,key=lambda x:x[0])
    return [[vals[((r if axis==0 else c)&1)] for c in range(w)] for r in range(h)]"}

