{"code":"def transform(grid):
    out=[r[:] for r in grid]
    from collections import Counter
    for i,row in enumerate(grid):
        # The regular field is periodic by column parity; in stripe examples
        # both parities simply have the same value.
        modes=[]
        for p in (0,1):
            vals=[v for j,v in enumerate(row) if j%2==p]
            modes.append(Counter(vals).most_common(1)[0][0] if vals else None)
        for j,v in enumerate(row):
            if modes[j%2] is not None and v != modes[j%2]:
                out[i][j]=modes[j%2]
    return out"}

