{"code":"def transform(grid):
    from collections import Counter
    out=[]
    for row in grid:
        c=Counter(row); top,n=c.most_common(1)[0]
        if n*2>=len(row):
            out.append([top]*len(row)); continue
        modes=[]
        for p in (0,1):
            vals=row[p::2]
            modes.append(Counter(vals).most_common(1)[0][0])
        out.append([modes[j%2] for j in range(len(row))])
    return out"}

